import React, { useState, useEffect } from "react";
import { fetchStructDataWithFilters } from "../api/fetch_records";
import { parseDMS } from "../utils/converters";

const EditableWaterReport = () => {
    // Храним счётные записи
  const [records, setRecords] = useState([]);
  // Поля, которые пользователь может сам дополнять (месяцы)
  const [formData, setFormData] = useState({ month1: "", month2: "", month3: "" });
  // const [formData, setFormData] = useState({
  //   organisation: "",
  //   address: "",
  //   inn: "",
  //   opf: "",
  //   district: "",
  //   region: "",
  //   reopCode: "",
  //   reopName: "",
  //   areaCode: "",
  //   areaName: "",
  //   agreement: "",
  //   meterType: "",
  //   checkDate: "",
  //   objectName: "",
  //   objectType: "",
  //   category: "",
  //   latitude: "",
  //   longitude: "",
  //   permittedVolume: "",
  //   actualVolume: "",
  //   month1: "",
  //   month2: "",
  //   month3: ""
  // });

    useEffect(() => {
    (async () => {
      const org = JSON.parse(localStorage.getItem("org") || "{}");
      if (!org.id) return console.error("org.id не найден");
      const resp = await fetchStructDataWithFilters("get_struct31", { org_id: org.id });
      if (!resp || resp.status !== "success") {
        console.error("Ошибка API:", resp?.message);
        return;
      }
      setRecords(resp.data || []);
    })();
  }, []);


  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  return (
    <div className="water-report">
      <h2>Сведения, полученные в результате учета объема забора (изъятия) водных ресурсов из водных объектов</h2>
      <div className="subtitle">за <select> <option value="">Выбрать</option>
                <option value="1">1 </option>
                <option value="2">2</option>
                <option value="3">3 </option>
                <option value="4">4</option>  
                </select> квартал <select> <option value="">Выбрать</option>
                <option value="2025">2025 </option>
                <option value="2024">2024</option>
                <option value="2023">2023 </option>
                <option value="2022">2022</option> </select>  г. | Форма 3.1</div>

      <table className="info-table">
        <tbody>
          <tr>
            <td>Наименование организации</td>
            <td colSpan="3">
              <input name="organisation" value={formData.organisation} onChange={handleChange} />
            </td>
          </tr>
          <tr>
            <td>Почтовый адрес</td>
            <td colSpan="3">
              <input name="address" value={formData.address} onChange={handleChange} />
            </td>
          </tr>
          <tr>
            <td>ИНН</td>
            <td><input name="inn" value={formData.inn} onChange={handleChange} /></td>
            <td>ОПФ</td>
            <td><input name="opf" value={formData.opf} onChange={handleChange} /></td>
          </tr>
          <tr>
            <td>Бассейновый округ</td>
            <td><input name="district" value={formData.district} onChange={handleChange} /></td>
            <td>Регион</td>
            <td><input name="region" value={formData.region} onChange={handleChange} /></td>
          </tr>
          <tr>
            <td>Наименование и код гидрографической единицы</td>
            <td >
              <select name="reopCode" value={formData.reopCode} onChange={handleChange}>
                <option value="">Выбрать</option>
                <option value="13.01.03.002">13.01.02</option>
                <option value="13.01.03.003">13.01.03</option>
              </select>
              </td>
              <td colSpan="2">
              <input name="reopName" value={formData.reopName} onChange={handleChange} />
            </td>
          </tr>
          <tr>
            <td>Водохозяйственный участок</td>
            <td >
              <select name="areaCode" value={formData.areaCode} onChange={handleChange}>
                <option value="">Выбрать</option>
                <option value="13.01.02.002">13.01.02.002</option>
                <option value="13.01.03.003">13.01.03.003</option>
              </select>
              </td>
              <td colSpan="2">
              <input name="areaName" value={formData.areaName} onChange={handleChange} />
            </td>
          </tr>
          <tr>
            <td>Реквизиты договора</td>
            <td colSpan="2">
            Регистрационный № Договора водопользования
              <input name="agreement" value={formData.agreement} onChange={handleChange} />
            </td>
            <tr>
            <td>
            Дата начало
            <input  type="date" name="agreement" value={formData.agreement} onChange={handleChange} />  
            </td>
            <td colSpan="1">Дата окончания
            <input  type="date" name="agreement" value={formData.agreement} onChange={handleChange} />  
            </td>
            </tr>
          </tr>
          <tr>
            <td>Марка прибора учета</td>
            <td colSpan="3"><input name="meterType" value={formData.meterType} onChange={handleChange} /></td>
            </tr>
            <tr>
            <td>Дата последний поверки, периодичность проверки</td>
            <td><input type="date" name="checkDate" value={formData.checkDate} onChange={handleChange} /></td>
            <td colSpan="2"><input name="checkDate" value={formData.checkDate} onChange={handleChange} ></input></td>
          </tr>
        </tbody>
      </table>

<table className="data-table">
  <thead>
    <tr>
      <th rowSpan="3">Наименование водного объекта - водоисточника</th>
      <th colSpan="3">Коды</th>
      <th rowSpan="3">№ точки водозабора</th>
      <th colSpan="6">Координаты водозабора</th>
      <th rowSpan="4">Объем допустимого водо-забора, тыс. м3</th>
      <th colSpan="5">Фактический объем забора, тыс. м3</th>
    </tr>
    <tr>
      <th rowSpan="2">вида водного объекта-водоисточника</th>
      <th rowSpan="2">водного объекта-водоисточника</th>
      <th rowSpan="2">категория качества воды</th>
      <th colSpan="3">северной широты</th>
      <th colSpan="3">восточной долготы</th>

      <th colSpan="4">в том числе по месяцам квартала</th>
    </tr>
    <tr>
      <th>град.</th>
      <th>мин.</th>
      <th>сек.</th>
      <th>град.</th>
      <th>мин.</th>
      <th>сек.</th>
      <th>всего</th>
      <th>1 мес.</th>
      <th>2 мес.</th>
      <th>3 мес.</th>
    </tr>
  </thead>
         <tbody>
          {records.map((rec, idx) => {
            // разбираем координаты
            const [latStr, lonStr] = (rec.latitude_longitude || "").split("_");
            const lat = parseFloat(latStr), lon = parseFloat(lonStr);
            const latD = parseDMS(lat), lonD = parseDMS(lon);

            return (
              <tr key={idx}>
                {/* Наименование водного объекта */}
                <td>
                  <input
                    name={`objectName_${idx}`}
                    value={rec.water_object?.name || ""}
                    readOnly
                  />
                </td>

                {/* Коды вида и объекта */}
                <td>
                  <input
                    name={`objectType_${idx}`}
                    value={rec.water_object?.code_type?.code || ""}
                    readOnly
                  />
                </td>
                <td>
                  <input
                    name={`objectCode_${idx}`}
                    value={rec.water_object?.code_obj?.code || ""}
                    readOnly
                  />
                </td>
                <td>
                  <input
                    name={`category_${idx}`}
                    value={rec.water_object?.category || ""}
                    readOnly
                  />
                </td>

                {/* № точки */}
                <td>
                  <input
                    name={`pointNumber_${idx}`}
                    value={rec.point_id}
                    readOnly
                  />
                </td>

                {/* Координаты DMS */}
                <td><input value={latD.deg} readOnly /></td>
                <td><input value={latD.min} readOnly /></td>
                <td><input value={latD.sec} readOnly /></td>
                <td><input value={lonD.deg} readOnly /></td>
                <td><input value={lonD.min} readOnly /></td>
                <td><input value={lonD.sec} readOnly /></td>

                {/* Объём допустимого */}
                <td>
                  <input
                    name={`allowedVolume_${idx}`}
                    value={rec.permission?.allowed_volume?.toLocaleString() || ""}
                    readOnly
                  />
                </td>

                {/* Фактический объём — если придёт */}
                <td>
                  <input
                    name={`actualVolume_${idx}`}
                    value={rec.permission?.actual_volume?.toLocaleString() || ""}
                    readOnly
                  />
                </td>

                {/* Пользовательские месячные данные */}
                <td>
                  <input
                    type="text"
                    name="month1"
                    value={formData.month1}
                    onChange={handleChange}
                  />
                </td>
                <td>
                  <input
                    type="text"
                    name="month2"
                    value={formData.month2}
                    onChange={handleChange}
                  />
                </td>
                <td>
                  <input
                    type="text"
                    name="month3"
                    value={formData.month3}
                    onChange={handleChange}
                  />
                </td>
              </tr>
            );
          })}

          {/* Если записей нет — показываем фидбэк */}
          {records.length === 0 && (
            <tr>
              <td colSpan="16" style={{ textAlign: "center", color: "#999" }}>
                Данные не загружены или отсутствуют
              </td>
            </tr>
          )}
        </tbody>
</table>
    </div>
  );
};

export default EditableWaterReport;
